INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2335525', 'Kaocen Revolt', 'The Kaocen revolt (Kabyle: Tagrawla n Kawsen) was a Tuareg rebellion against French colonial rule of the area around the Aïr Mountains of northern Niger during 1916–17.', 1916, NULL, NULL, 1917, NULL, NULL, 'year', '1916–1917', 50, 'https://en.wikipedia.org/wiki/Kaocen_revolt'),
  ('Q4114547', '1974 Nigerien coup d''état', 'The 1974 Nigerien coup d''état was a largely bloodless military insurrection which overthrew the first postcolonial government of Niger. The government that followed, while plagued by coup attempts of its own, survived until 1991.', 1974, 4, 15, NULL, NULL, NULL, 'day', '15 April 1974', 37, 'https://en.wikipedia.org/wiki/1974_Nigerien_coup_d''%C3%A9tat'),
  ('Q1488972', 'UTA 772 bombing', 'UTA Flight 772 was a scheduled international passenger flight of the French airline Union de Transports Aériens (UTA) operating from Brazzaville in the People''s Republic of the Congo, via N''Djamena in Chad, to Charles de Gaulle Airport in Paris, France. On 19 September 1989, the McDonnell Douglas DC-10 operating the flight crashed into the Ténéré desert near Bilma, Niger, killing all 170 people on board after an in-flight explosion caused by a suitcase bomb.', 1989, 9, 19, NULL, NULL, NULL, 'day', '19 September 1989', 57, 'https://en.wikipedia.org/wiki/UTA_Flight_772'),
  ('Q4114548', '1996 Nigerien coup d''état', 'The 1996 Nigerien coup d''état was a military coup d''état which occurred on 27 January 1996 in Niamey, Niger. It ousted Niger''s first democratically elected president, Mahamane Ousmane after nearly three years in power and installed General Ibrahim Baré Maïnassara as head of state.', 1996, 1, 27, NULL, NULL, NULL, 'day', '27 January 1996', 39, 'https://en.wikipedia.org/wiki/1996_Nigerien_coup_d''%C3%A9tat'),
  ('Q16266489', '1999 Nigerien coup d''état', 'The 1999 Nigerien coup d''état occurred on 9 April 1999 and resulted in the death of President Ibrahim Baré Maïnassara and the installation of Daouda Malam Wanké as President on 11 April. Maïnassara was shot under unclear circumstances in an ambush at either Diori Hamani International Airport, potentially while attempting to flee the country, or at a military base, likely by members of the Presidential Guard.', 1999, 4, 9, NULL, NULL, NULL, 'day', '9 April 1999', 43, 'https://en.wikipedia.org/wiki/1999_Nigerien_coup_d''%C3%A9tat'),
  ('Q632787', 'Insurgency in the Maghreb', 'An Islamist insurgency is taking place in the Maghreb region of North Africa, followed on from the end of the Algerian Civil War in 2002. The Algerian militant group Salafist Group for Preaching and Combat (GSPC) allied itself with al-Qaeda to eventually become al-Qaeda in the Islamic Maghreb (AQIM).', 2002, 4, 11, NULL, NULL, NULL, 'day', '11 April 2002', 58, 'https://en.wikipedia.org/wiki/Insurgency_in_the_Maghreb_(2002%E2%80%93present)'),
  ('Q2579041', '2009–2010 West African meningitis outbreak', 'The 2009–2010 West African meningitis outbreak was an epidemic of bacterial meningitis which occurred in Burkina Faso, Mali, Niger, and Nigeria since January 2009, an annual risk in the African meningitis belt. A total of 13,516 people have been infected with meningitis, and 931 have died.', 2009, 1, NULL, 2010, NULL, NULL, 'month', 'January 2009 – 2010', 43, 'https://en.wikipedia.org/wiki/2009%E2%80%932010_West_African_meningitis_outbreak'),
  ('Q924625', '2010 Nigerien coup d''état', 'A coup d''état occurred in Niger on 18 February 2010. Soldiers attacked the presidential palace in Niamey under weapons fire at midday and captured President Mamadou Tandja, who was chairing a government meeting at the time.', 2010, 2, 18, NULL, NULL, NULL, 'day', '18 February 2010', 56, 'https://en.wikipedia.org/wiki/2010_Nigerien_coup_d''%C3%A9tat'),
  ('Q13548627', 'Battle of Agadez and Arlit', 'On 23 May 2013, two coordinated attacks perpetrated by Islamist affiliates targeted the two Niger towns of Agadez and Arlit, the first being a military base the other a French-owned and operated uranium mine. In the first attack on the Niger military base, in which eight attackers participated, 23 soldiers and a civilian were confirmed dead by the next day.', 2013, 5, 23, NULL, NULL, NULL, 'day', '23 May 2013', 43, 'https://en.wikipedia.org/wiki/Agadez_and_Arlit_attacks'),
  ('Q15651790', 'massacre', 'The Kawuri massacre happened on 26 January 2014 in Kawuri, a village in Konduga Local Government Area, 37 km (23 mi) southeast of Maiduguri in Borno State, northeastern Nigeria. About 50 insurgents attacked civilians with bombs and guns.', 2014, 1, 26, NULL, NULL, NULL, 'day', '26 January 2014', 34, 'https://en.wikipedia.org/wiki/Kawuri_massacre'),
  ('Q16761579', '2014 Gamboru Ngala attack', 'On the night of 5–6 May 2014, Boko Haram militants attacked the twin towns of Gamboru and Ngala in Borno State, northeastern Nigeria. About 310 residents were killed in the 12-hour massacre, and the town was largely destroyed.', 2014, 5, 5, NULL, NULL, NULL, 'day', '5 May 2014', 37, 'https://en.wikipedia.org/wiki/2014_Gamboru_Ngala_massacre'),
  ('Q20639688', 'July 2015 Kukawa massacre', 'On 1 July 2015, Boko Haram gunmen stormed the village of Kukawa, in Borno State and killed 97 people. According to an anonymous senior government official, the militants targeted mosques, which they believed taught a form of Islam that was too moderate.', 2015, 7, 1, NULL, NULL, NULL, 'day', '1 July 2015', 37, 'https://en.wikipedia.org/wiki/30_June_and_1_July_2015_Borno_massacres'),
  ('Q27629826', '2016 Niger flood', 'Heavy rains during the months of June, July and August 2016 resulted in extreme flooding of various rivers throughout Niger, particularly the Niger River, where the floods caused material damage and loss of life in Niger and other countries along the river''s path. Since 2000, flooding in Niger has intensified, with the most serious threats concentrated in the southwestern part of Niger and along the banks of the Niger River.', 2016, NULL, NULL, 2016, 9, NULL, 'year', '2016', 34, 'https://en.wikipedia.org/wiki/2016_Niger_flood'),
  ('Q81674042', '2020 Tillabéri attack', 'On 9 January 2020, a large group of Islamic State in the Greater Sahara militants assaulted a Nigerien military base at Chinagodrar, in Niger''s Tillabéri Region. They attacked an army post in Chinagodrar, in the west of the country, in Tillabéri Region, 13 kilometres (8 miles) from the border with Mali, 210 kilometres (130 miles) north of Niamey.', 2020, 1, 9, NULL, NULL, NULL, 'day', '9 January 2020', 39, 'https://en.wikipedia.org/wiki/Battle_of_Chinagodrar'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q104635416', '2021 Niger border attacks', 'The Tchoma Bangou and Zaroumdareye massacres took place on January 2, 2021, when 105 people were killed and 75 injured in attacks by Islamic State in the Greater Sahara on the villages of Tchoma Bangou and Zaroumdareye in Tondikiwindi, Ouallam Department, Niger. The massacres were one of the deadliest events in Nigerien history.', 2021, 1, 2, NULL, NULL, NULL, 'day', '2 January 2021', 43, 'https://en.wikipedia.org/wiki/Tchoma_Bangou_and_Zaroumdareye_massacres'),
  ('Q117100709', '2023 Nigerien coup d''état', 'On 26 July 2023, a coup d''état occurred in Niger when the presidential guard detained President Mohamed Bazoum, and presidential guard commander General Abdourahamane Tiani proclaimed himself the leader of a military junta shortly after confirming the coup a success. This was the fifth military coup d''état since the country gained independence from France in 1960, and the first since 2010.', 2023, 7, 26, NULL, NULL, NULL, 'day', '26 July 2023', 73, 'https://en.wikipedia.org/wiki/2023_Nigerien_coup_d''%C3%A9tat'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods');
